'use strict';

/**
* Split a tidy data set into multiple data sets according to a specified key.
*
* @module @stdlib/plot/vega/data/tidy/split-on-key
*
* @example
* var objarray2tidy = require( '@stdlib/plot/vega/data/tidy/from-object-array' );
* var splitOnKey = require( '@stdlib/plot/vega/data/tidy/split-on-key' );
*
* var x = [
*     {
*         'x': 0,
*         'y': 1
*     },
*     {
*         'x': 1,
*         'y': 2
*     },
*     {
*         'x': 0,
*         'y': 3
*     }
* ];
*
* var v = splitOnKey( objarray2tidy( x, 'series' ), 'x' );
* // returns [ <DataSet>, <DataSet> ]
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
